def records():
    return json.loads(gzip.decompress(base64.b64decode("".join(PAYLOAD.split()))).decode("utf-8"))


def apply(a):
    from engine.normalizer.canonical import normalize_text
    recs = records()
    ids = [r["id"] for r in recs]
    if len(ids) != EXPECTED or len(set(ids)) != EXPECTED:
        raise SystemExit("RECORD_COUNT: %d (المتوقع %d بلا تكرار)" % (len(ids), EXPECTED))
    if any(not any(i.startswith(p) for p in PREFIXES) for i in ids):
        raise SystemExit("RECORD_PREFIX: معرّف خارج البادئات السبع")
    bad = [(r["id"], m) for r in recs for m in PUBLISHER_MARKS if m in r["title"] or m in r["text"]]
    if bad:
        raise SystemExit("PUBSCRUB_FAIL: %s" % bad[:5])
    conn = psycopg.connect(os.environ["DATABASE_URL"])
    try:
        with conn.cursor() as cur:
            pats = tuple(p + "%" for p in PREFIXES)
            cur.execute("SELECT id FROM knowledge_objects WHERE " + " OR ".join("id LIKE %s" for _ in PREFIXES), pats)
            existing = {x[0] for x in cur.fetchall()}
            foreign = sorted(existing - set(ids))
            if foreign:
                raise SystemExit("PREFIX_COLLISION: %d معرّفًا قائمًا ليس من هذه الدفعة: %s" % (len(foreign), foreign[:10]))
            print("PREFIX_OK: قائم سلفًا من هذه الدفعة %d، والجديد %d" % (len(existing), len(ids) - len(existing)))
            # لقطة كاملة لكل صفّ قائم سيُحدَّث — فالتراجع عند إعادة التشغيل يُعيد النصوص القديمة لا يحذف الجديد وحده
            cur.execute("SELECT row_to_json(k)::text FROM knowledge_objects k WHERE id = ANY(%s) ORDER BY id",
                        (sorted(existing),))
            snap = [x[0] for x in cur.fetchall()]
            with open(a.snapshot_out, "w", encoding="utf-8") as f:
                f.write("\n".join(snap) + ("\n" if snap else ""))
            print("SNAPSHOT: %d صفًّا قائمًا ← %s" % (len(snap), a.snapshot_out))
            cur.execute("SELECT count(*) FROM knowledge_objects")
            n_before = cur.fetchone()[0]
            cur.execute(FP_OUT, pats)
            fp_before = cur.fetchone()[0]
            for r in recs:
                cur.execute(INSERT_SQL, {"id": r["id"], "object_type": r["object_type"], "branch": r["branch"],
                                         "topic": r["topic"], "subtopic": r["subtopic"], "title": r["title"],
                                         "original_text": r["text"], "normalized_text": normalize_text(r["text"]),
                                         "verification_status": r["verification_status"],
                                         "metadata": Jsonb(r["metadata"])})
            cur.execute(FP_OUT, pats)
            if cur.fetchone()[0] != fp_before:
                raise SystemExit("SCOPE_BREACH: تغيّر صفٌّ خارج البادئات السبع")
            cur.execute("SELECT count(*) FROM knowledge_objects")
            if cur.fetchone()[0] != n_before + len(set(ids) - existing):
                raise SystemExit("COUNT_UNEXPECTED")
            by = {}
            for r in recs:
                p = next(p for p in PREFIXES if r["id"].startswith(p))
                s = by.setdefault(p, [0, 0])
                s[0] += 1
                s[1] += bool(r["metadata"].get("extraction_uncertain"))
            for p, (n, f) in sorted(by.items()):
                print("  %-16s %4d كائنًا | موسوم للمراجعة: %d" % (p.rstrip("-"), n, f))
        conn.commit()
    except BaseException as e:
        conn.rollback()
        print("ROLLED_BACK: %s" % e)
        raise
    finally:
        conn.close()
    new = sorted(set(ids) - existing)
    with open(a.ids_out, "w", encoding="utf-8") as f:
        f.write("\n".join(new) + ("\n" if new else ""))
    print("NEW_IDS: %d ← %s" % (len(new), a.ids_out))
    print("INGEST_REFMISSING_OK")


def rollback(path):
    ids = [l.strip() for l in open(path, encoding="utf-8") if l.strip()]
    if not ids:
        print("ROLLBACK_NOTHING")
        return
    if any(not any(i.startswith(p) for p in PREFIXES) for i in ids):
        raise SystemExit("ROLLBACK_REFUSED: ملف المعرّفات فيه ما ليس من هذه الدفعة")
    with psycopg.connect(os.environ["DATABASE_URL"]) as conn, conn.cursor() as cur:
        cur.execute("DELETE FROM knowledge_objects WHERE id = ANY(%s)", (ids,))
        n = cur.rowcount
        conn.commit()
    print("PG_DELETED: %d" % n)
    try:
        os.chdir(ROOT)
        from engine import legalmind_engine as eng
        from engine import embedding
        eng.qdrant_request("POST", f"/collections/{eng.COLLECTION}/points/delete?wait=true",
                           {"points": [embedding.point_id(i) for i in ids]})
        print("QDRANT_DELETED: %d نقطة" % len(ids))
    except Exception as e:      # لا يُبتلع: يُطبع ويُعاد رمز فشل
        print("QDRANT_DELETE_FAILED: %s" % e)
        sys.exit(2)
    print("ROLLBACK_DONE")


def restore(path):
    """يعيد الصفوف القائمة قبل التشغيل من لقطتها حرفيًا (كل الأعمدة) — للتراجع عند إعادة التشغيل."""
    rows = [json.loads(l) for l in open(path, encoding="utf-8") if l.strip()]
    if not rows:
        print("RESTORE_NOTHING")
        return
    if any(not any(r["id"].startswith(p) for p in PREFIXES) for r in rows):
        raise SystemExit("RESTORE_REFUSED: في اللقطة ما ليس من البادئات السبع")
    with psycopg.connect(os.environ["DATABASE_URL"]) as conn, conn.cursor() as cur:
        cur.execute("SELECT column_name FROM information_schema.columns WHERE table_name = 'knowledge_objects' "
                    "AND column_name <> 'id' ORDER BY ordinal_position")
        cols = [x[0] for x in cur.fetchall()]
        sql = ("UPDATE knowledge_objects k SET " + ", ".join('"%s" = r."%s"' % (c, c) for c in cols) +
               " FROM jsonb_populate_record(NULL::knowledge_objects, %s::jsonb) r WHERE k.id = r.id")
        for r in rows:
            cur.execute(sql, (json.dumps(r, ensure_ascii=False),))
            if cur.rowcount != 1:
                raise SystemExit("RESTORE_MISS: %s" % r["id"])
        conn.commit()
    print("PG_RESTORED: %d" % len(rows))
    print("RESTORE_DONE")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--ids-out")
    ap.add_argument("--snapshot-out")
    ap.add_argument("--rollback")
    ap.add_argument("--restore")
    a = ap.parse_args()
    if a.rollback:
        return rollback(a.rollback)
    if a.restore:
        return restore(a.restore)
    if not a.ids_out or not a.snapshot_out:
        raise SystemExit("IDS_OUT_MISSING: --ids-out و--snapshot-out كلاهما لازم")
    apply(a)


if __name__ == "__main__":
    main()
